--
-- Table structure for table `kelas_riwayat`
--

DROP TABLE IF EXISTS `kelas_riwayat`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kelas_riwayat` (
  `id` int NOT NULL AUTO_INCREMENT,
  `jenjang` varchar(20) DEFAULT NULL,
  `tapel` varchar(20) DEFAULT NULL,
  `tingkat` varchar(20) DEFAULT NULL,
  `kelas` varchar(20) DEFAULT NULL,
  `id_walas` varchar(10) DEFAULT NULL,
  `id_ruang` int DEFAULT NULL,
  `kertas` varchar(20) DEFAULT 'F4',
  `orientasi` varchar(20) DEFAULT 'Portait',
  `margin_left` float DEFAULT '1',
  `margin_top` float DEFAULT '1',
  `margin_right` float DEFAULT '1',
  `margin_bottom` float DEFAULT '1',
  `tinggi_baris` float DEFAULT '0.6',
  `kolom_nama` float DEFAULT '6',
  `kolom_pelajaran` float DEFAULT '0.5',
  `kkm` float DEFAULT '60',
  `show_ttd_walas` tinyint DEFAULT '1',
  `x_walas` float DEFAULT '0',
  `y_walas` float DEFAULT '0',
  `size_walas` float DEFAULT '2',
  `x_mudir` float DEFAULT '0',
  `y_mudir` float DEFAULT '0',
  `size_mudir` float DEFAULT '1.5',
  `setting_rapor` json DEFAULT NULL,
  `setting_rekap_nilai` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_kelas` (`kelas`) /*!80000 INVISIBLE */,
  KEY `idx_id_kelas` (`kelas`,`id`) /*!80000 INVISIBLE */,
  KEY `idx_walas` (`id_walas`),
  KEY `jenjang_tapel` (`jenjang`,`tapel`),
  KEY `idx_jenjang_tapel_group` (`jenjang`,`tapel`,`id`,`tingkat`,`kelas`,`id_walas`),
  KEY `idx_kr_opt` (`jenjang`,`tapel`,`kelas`,`id_walas`)
) ENGINE=InnoDB AUTO_INCREMENT=541 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

