--
-- Table structure for table `siswa_riwayat`
--

DROP TABLE IF EXISTS `siswa_riwayat`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `siswa_riwayat` (
  `id` int NOT NULL AUTO_INCREMENT,
  `jenjang` varchar(10) DEFAULT NULL,
  `tapel` varchar(10) DEFAULT NULL,
  `tingkat` varchar(10) DEFAULT NULL,
  `kelas` varchar(10) DEFAULT NULL,
  `nis_lokal` varchar(20) NOT NULL,
  `no_urut` int DEFAULT NULL,
  `tgl_masuk` date DEFAULT NULL,
  `status_awal` varchar(20) DEFAULT NULL,
  `status_akhir` varchar(20) DEFAULT NULL,
  `is_active` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tapel_kelas` (`tapel`,`tingkat`,`kelas`) /*!80000 INVISIBLE */,
